<template>
  <Stepper v-model="stepIndex" class="flex w-full items-start gap-2">
    <StepperItem
      v-for="(step, index) in steps"
      :key="step.step"
      v-slot="{ state }"
      class="relative flex w-full flex-col items-center justify-center"
      :step="step.step"
      :class="[index === 0 && 'items-start', index === steps.length - 1 && 'items-end']"
    >
      <StepperSeparator
        v-if="step.step !== steps[steps.length - 1].step"
        class="absolute left-0 -right-full top-5 block h-0.5 shrink-0 rounded-full bg-muted group-data-[state=completed]:bg-primary"
        :class="[state === 'completed' && '!bg-blue-600']"
      />

      <Button
        :variant="state === 'completed' || state === 'active' ? 'default' : 'outline'"
        class="z-10 rounded-full shrink-0 w-11 h-11 border-accent-foreground cursor-default"
        :class="[
          state === 'active' && 'border-2 border-blue-600 bg-background hover:bg-background',
          state === 'completed' && 'bg-blue-600 hover:bg-blue-600',
          state === 'inactive' && 'hover:bg-background',
        ]"
      >
        <Check v-if="state === 'completed'" class="!size-5" />
        <Circle v-if="state === 'active'" class="!size-5 text-blue-600" />
        <Dot v-if="state === 'inactive'" />
      </Button>

      <div class="flex flex-col items-center text-center">
        <StepperTitle
          class="text-sm font-medium text-accent-foreground"
          :class="[state === 'active' && 'text-blue-600', state === 'completed' && 'text-blue-600']"
        >
          {{ step.title }}
        </StepperTitle>
      </div>
    </StepperItem>
  </Stepper>
</template>

<script setup lang="ts">
import { Check, Circle, Dot } from 'lucide-vue-next';

const stepIndex = defineModel<number>({ required: true });

const steps = [
  { step: 1, title: 'Create Account' },
  { step: 2, title: 'Confirm Email' },
  { step: 3, title: 'Log In' },
];
</script>

<style scoped lang="scss"></style>
